INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000051',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about future plans in Hindi","Use kal/agle hafte X karna hai for plans","Express intentions and arrangements"],"explanation":{"intro":"Talking about plans covers how to describe what you intend to do — tomorrow, next week, or next month — using future expressions in Hindi.","culturalNote":"Planning in Indian culture: kal (tomorrow/yesterday — same word!), agle hafte (next week), agle mahine (next month). Plans are often tentative in Indian culture — inshallah (if God wills), agar sab theek raha (if all goes well), bhagwan ke haath mein hai (it is in God''s hands) are common qualifiers. Indian families discuss plans collectively — individual plans often involve family consultation. Key planning contexts: wedding planning (shaadi ki taiyaari), exam preparation (pariksha ki taiyaari), pilgrimage (tirth yatra). Spontaneity vs. planning: urban India plans like any modern society; rural India plans around seasons, harvest, and festivals. India has long-term planning too — Five-Year Plans (Panch-Varshiya Yojana) were replaced by NITI Aayog."},"examples":[{"sentence":"Kal mujhe doctor ke paas jaana hai.","english":"Tomorrow I need to go to the doctor."},{"sentence":"Agle mahine hum Shimla jaane ka plan hai.","english":"Next month we have a plan to go to Shimla."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about future plans and intentions in Hindi."}}',
'{"items":[{"word":"kal","translation":"tomorrow / yesterday (context determines)","transliteration":"kal","pronunciation":"kal","example":"kal jaana hai"},{"word":"agle hafte","translation":"next week","transliteration":"agle hafte","pronunciation":"AG-le HAF-te","example":"agle hafte milenge"},{"word":"plan","translation":"plan","transliteration":"plan","pronunciation":"plan","example":"plan banana"},{"word":"irada","translation":"intention","transliteration":"irada","pronunciation":"i-RA-da","example":"mera irada"},{"word":"taiyaari","translation":"preparation","transliteration":"taiyaari","pronunciation":"tai-YAAR-ee","example":"taiyaari karna"},{"word":"agle mahine","translation":"next month","transliteration":"agle mahine","pronunciation":"AG-le ma-HEE-ne","example":"agle mahine"}]}',
'{"title":"Mujhe X jaana hai — I need/have to go to X (obligation with jaana hai)","pattern":"Mujhe X karna hai = I need to do X / I have to do X. Mujhe (dative — to me) + infinitive + hai = obligation/necessity. Mujhe jaana hai = I need to go. Mujhe khaana hai = I need to eat. Future: kal mujhe jaana hai = tomorrow I need to go. This is the most common way to express immediate or scheduled obligation in Hindi.","explanation":"Mujhe X karna hai: the most natural way to say ''I need to / have to'' in Hindi. Mujhe = dative of main (to me / I must). X karna = the infinitive. Hai = is (confirms the obligation). Negative: mujhe nahi jaana (I don''t need to go). Question: kya tumhe jaana hai? (do you need to go?). Compare with chahiye: mujhe X chahiye = I want/need X (noun); mujhe X karna hai = I need to do X (action). Both use dative subject mujhe.","examples":[{"sentence":"Aaj mujhe ghar ki safai karni hai.","english":"Today I need to clean the house."},{"sentence":"Kya tumhe office jaana hai?","english":"Do you need to go to the office?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kal means?","options":["tomorrow/yesterday","today","now","later"],"correctAnswer":"tomorrow/yesterday"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tomorrow I need to go to the doctor.","options":["Kal mujhe doctor ke paas jaana hai.","Aaj mujhe doctor ke paas jaana hai.","Kal tumhe doctor ke paas jaana hai.","Kal mujhe hospital jaana hai."],"correctAnswer":"Kal mujhe doctor ke paas jaana hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Aaj mujhe ghar ki safai ___ hai.","options":["karni","karna","karte","karti"],"correctAnswer":"karni"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Do you need to go to the office?","wordBankItems":["Kya","tumhe","office","jaana","hai","?"],"correctAnswer":"Kya tumhe office jaana hai ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"taiyaari means?","options":["preparation","plan","intention","arrangement"],"correctAnswer":"preparation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000052',1,'APPROVED','PUBLISHED',
'{"objectives":["Ask for and grant permissions in Hindi","Use kya main X kar sakta hoon for permission","Respond to requests politely"],"explanation":{"intro":"Permissions and requests covers asking if you may do something, granting or refusing permission, and making polite requests in Hindi.","culturalNote":"Permission-seeking in Indian culture: hierarchical — you always ask permission from elders, bosses, hosts. Kya main X kar sakta hoon? = May I do X? (male speaker). Responses: haan, zaroor (yes, certainly), bilkul (absolutely), nahi, mat karo (no, don''t), please nahi (please no — code-switching common). Children ask permission from parents, students from teachers, employees from bosses. Joint family: permissions involve more stakeholders. Guest culture: atithi devo bhava (the guest is God) — guests are encouraged, not permission-denied. Office culture: more hierarchical than Western — ''may I leave early?'' common. Leave applications (chhuti ki arzi) — formal written permission requests — important Indian institution from school onwards."},"examples":[{"sentence":"Kya main andar aa sakta hoon?","english":"May I come inside?"},{"sentence":"Haan, zaroor aao — aapka swagat hai.","english":"Yes, certainly come — you are welcome."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask for and grant permission in Hindi."}}',
'{"items":[{"word":"izaajat","translation":"permission","transliteration":"izaajat","pronunciation":"i-ZAA-jat","example":"izaajat maangna"},{"word":"zaroor","translation":"certainly/definitely","transliteration":"zaroor","pronunciation":"za-ROOR","example":"haan zaroor"},{"word":"mat karo","translation":"don''t do (informal)","transliteration":"mat karo","pronunciation":"mat KA-ro","example":"mat karo"},{"word":"swagat","translation":"welcome","transliteration":"swagat","pronunciation":"SWA-gat","example":"swagat hai"},{"word":"bilkul","translation":"absolutely","transliteration":"bilkul","pronunciation":"BIL-kul","example":"bilkul theek"},{"word":"mana","translation":"forbidden/not allowed","transliteration":"mana","pronunciation":"ma-NA","example":"yahan mana hai"}]}',
'{"title":"Kya main X kar sakta/sakti hoon — May I do X? (permission request)","pattern":"Kya main X kar sakta hoon? (male) / sakti hoon? (female) = May I do X? / Can I do X? Kya = question marker. main = I. X karna = the activity. sakna = can/be able to. Hoon = am (1st person). Formal: kya main X kar sakta hoon? Informal: main X kar sakta hoon? (rising intonation).","explanation":"Permission questions: kya main X kar sakta/sakti hoon? is the standard way to ask permission (''May I?''). Sakna = can modal — also used for ability (I can speak Hindi = main Hindi bol sakta hoon) — context determines whether it is ability or permission. Responding: haan, zaroor (yes certainly), haan, kar sakte ho (yes you can), nahi, mat karo (no, don''t), maafi chahiye lekin nahi (sorry but no). Variant: kya aap X kar sakte hain? = can you do X? (asking someone else to do something for you).","examples":[{"sentence":"Kya main yahan baith sakta hoon?","english":"May I sit here?"},{"sentence":"Haan, bilkul baith sakte hain.","english":"Yes, absolutely you may sit."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"izaajat means?","options":["permission","request","welcome","refusal"],"correctAnswer":"permission"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"May I come inside?","options":["Kya main andar aa sakta hoon?","Kya main bahar ja sakta hoon?","Kya aap andar aa sakte hain?","Kya main yahan baith sakta hoon?"],"correctAnswer":"Kya main andar aa sakta hoon?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Haan, bilkul baith ___ hain.","options":["sakte","sakta","sakti","sakna"],"correctAnswer":"sakte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: May I sit here?","wordBankItems":["Kya","main","yahan","baith","sakta","hoon","?"],"correctAnswer":"Kya main yahan baith sakta hoon ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"swagat means?","options":["welcome","permission","greeting","goodbye"],"correctAnswer":"welcome"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000053',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about past events in Hindi","Use kal and pichhle hafte for past time references","Narrate simple past events"],"explanation":{"intro":"Talking about the past covers past time references, simple past narration, and how to tell a story about recent events in Hindi.","culturalNote":"Past time expressions in Hindi: kal = yesterday (same word as tomorrow — context distinguishes), parson = day before yesterday (also day after tomorrow!), pichhle hafte = last week, pichhle mahine = last month, pichhle saal = last year, pehle = before/previously, us waqt = at that time. Hindi uses perfective past for completed actions. Story-telling: kahani sunana (telling a story) is deeply embedded in Indian culture — oral tradition, grandmothers telling stories at night (dadi/naani ki kahaaniyaan). Panchatantra (Sanskrit fables), Jataka tales (Buddhist). Modern: Bollywood films are heavily narrative — plot-driven, emotional story arcs. Cricket commentary is a form of live story-telling — Indian commentators are famous for dramatic narration."},"examples":[{"sentence":"Kal main bazar gaya aur khana kharida.","english":"Yesterday I went to the market and bought food."},{"sentence":"Pichhle hafte humne ek film dekhi.","english":"Last week we watched a film."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can narrate simple past events in Hindi."}}',
'{"items":[{"word":"kal","translation":"yesterday (also tomorrow — context)","transliteration":"kal","pronunciation":"kal","example":"kal gaya"},{"word":"parson","translation":"day before yesterday","transliteration":"parson","pronunciation":"PAR-son","example":"parson aaya"},{"word":"pichhle hafte","translation":"last week","transliteration":"pichhle hafte","pronunciation":"PICHH-le HAF-te","example":"pichhle hafte"},{"word":"pehle","translation":"before/previously/first","transliteration":"pehle","pronunciation":"PEH-le","example":"pehle jaana"},{"word":"gaya/gayi","translation":"went (m/f)","transliteration":"gaya/gayi","pronunciation":"GA-ya/GA-yi","example":"main gaya"},{"word":"dekha/dekhi","translation":"saw/watched (m/f)","transliteration":"dekha/dekhi","pronunciation":"DEK-ha/DEK-hi","example":"film dekhi"}]}',
'{"title":"Past tense narration — gaya, kiya, dekha, kharida (intransitive vs transitive)","pattern":"Intransitive past: main gaya (I went — no ne). Transitive past: maine film dekhi (I watched a film — ne required, verb agrees with object). Key distinction: jaana (intransitive) → gaya/gayi/gaye/gayi, no ne. Khaana khaana (transitive) → ne + khaya/khayee (agrees with khaana = masculine). Dekhe: maine film dekhi (feminine film → dekhi).","explanation":"Past tense split: intransitive verbs (jaana, aana, hona, sona, rona, hasna) → no ne, verb agrees with subject. Transitive verbs (karna, khaana, dekhna, kharidna, padhna, likhna) → subject takes ne, verb agrees with object. Key irregulars: jaana → gaya/gayi/gaye. aana → aaya/aayi/aaye. hona → hua/hui/hue. karna → kiya/ki/kiye. dekhna → dekha/dekhi/dekhe. If object is feminine: use feminine past. If object is masculine: use masculine past. If no direct object: use masculine singular as default.","examples":[{"sentence":"Wo kal school nahi aayi.","english":"She did not come to school yesterday."},{"sentence":"Humne pichhle saal Agra dekha.","english":"Last year we saw Agra (visited Agra)."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"parson means?","options":["day before yesterday","yesterday","last week","a long time ago"],"correctAnswer":"day before yesterday"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Yesterday I went to the market and bought food.","options":["Kal main bazar gaya aur khana kharida.","Kal main ghar gaya aur khana banaya.","Aaj main bazar gaya aur khana kharida.","Kal main bazar gayi aur khana kharida."],"correctAnswer":"Kal main bazar gaya aur khana kharida."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Humne pichhle saal Agra ___ .","options":["dekha","dekhi","dekhe","dekhte"],"correctAnswer":"dekha"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Last week we watched a film.","wordBankItems":["Pichhle","hafte","humne","ek","film","dekhi","."],"correctAnswer":"Pichhle hafte humne ek film dekhi ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"pehle means?","options":["before/previously","after","now","then"],"correctAnswer":"before/previously"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000054',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about food preferences and diet in Hindi","Use mujhe X pasand hai for food likes","Describe dietary restrictions"],"explanation":{"intro":"Food preferences and diet vocabulary covers likes and dislikes, dietary restrictions, and how to describe what you eat and why in Hindi.","culturalNote":"Indian dietary culture: vegetarianism (shakaahaar = plant-based diet) is extremely common — India has the largest vegetarian population in the world (~400 million). Religious dietary rules: Hindus often avoid beef, Muslims avoid pork, Jains avoid root vegetables and often all animal products. Non-vegetarian (maansaahaar): chicken, mutton (goat), fish. Regional variation: coastal regions eat fish, Bengali love fish (maachh), Rajasthan is heavily vegetarian. Spice levels: mirchi (chilli) — Indians generally eat much spicier food than Westerners. ''Tikha nahi chahiye'' (don''t want it spicy) is a common foreigner request. Key food words: chawal (rice), roti (flatbread), dal (lentils), sabzi (vegetables), dahi (yoghurt), ghee (clarified butter — essential in Indian cooking). Street food: golgappa, chaat, vada pav, samosa, jalebi."},"examples":[{"sentence":"Mujhe teekhaa khaana pasand nahi hai.","english":"I don''t like spicy food."},{"sentence":"Main shakaahaaree hoon, main maas nahi khaata.","english":"I am vegetarian, I don''t eat meat."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my food preferences and dietary restrictions in Hindi."}}',
'{"items":[{"word":"teekhaa","translation":"spicy/hot","transliteration":"teekhaa","pronunciation":"TEE-khaa","example":"teekhaa khaana"},{"word":"meetha","translation":"sweet","transliteration":"meetha","pronunciation":"MEE-tha","example":"meetha mithai"},{"word":"shakaahaaree","translation":"vegetarian","transliteration":"shakaahaaree","pronunciation":"sha-kaa-HAA-ree","example":"main shakaahaaree hoon"},{"word":"parhez","translation":"dietary restriction/abstinence","transliteration":"parhez","pronunciation":"par-HEZ","example":"parhez karna"},{"word":"dahi","translation":"yoghurt/curd","transliteration":"dahi","pronunciation":"DA-hi","example":"dahi khaana"},{"word":"ghee","translation":"clarified butter","transliteration":"ghee","pronunciation":"ghee","example":"ghee daalna"}]}',
'{"title":"Main X nahi khaata/khaati — I don''t eat X (habitual negation)","pattern":"Main X nahi khaata (male) / khaati (female) = I don''t eat X. Habitual present negative: nahi + verb. khaana = to eat → khaata/khaati/khaate (habitual present). Main maas nahi khaata = I don''t eat meat (permanent dietary habit). Main doodh nahi peeta = I don''t drink milk. Agreement: khaata (male speaker), khaati (female speaker).","explanation":"Habitual negative: main X nahi khaata/khaati. This is the standard form for talking about permanent dietary habits or restrictions. khaata hai (positive habitual) → nahi khaata (negative habitual — hai is dropped in negative). Same for other verbs: nahi jaata (don''t go), nahi sunta (don''t listen), nahi peeta (don''t drink). Note: this is different from ''I am not eating'' (present continuous): main nahi kha raha (I''m not eating right now — temporary). Habitual = permanent habit/rule.","examples":[{"sentence":"Wo alcohol nahi peeta.","english":"He doesn''t drink alcohol."},{"sentence":"Hum log pyaaz-lahsun nahi khaate.","english":"We don''t eat onion and garlic."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"teekhaa means?","options":["spicy/hot","sweet","sour","salty"],"correctAnswer":"spicy/hot"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am vegetarian, I don''t eat meat.","options":["Main shakaahaaree hoon, main maas nahi khaata.","Main shakaahaaree hoon, main maas nahi khaati.","Main maansaahaaree hoon, main maas khaata hoon.","Main shakaahaaree hoon, main machli nahi khaata."],"correctAnswer":"Main shakaahaaree hoon, main maas nahi khaata."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wo alcohol nahi ___ .","options":["peeta","peeti","peete","pi raha"],"correctAnswer":"peeta"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I don''t like spicy food.","wordBankItems":["Mujhe","teekhaa","khaana","pasand","nahi","hai","."],"correctAnswer":"Mujhe teekhaa khaana pasand nahi hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"parhez means?","options":["dietary restriction","preference","recipe","diet"],"correctAnswer":"dietary restriction"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000055',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about school and university in Hindi","Use X mein padhna for studying at a place","Describe subjects and academic life"],"explanation":{"intro":"School and university vocabulary covers educational institutions, subjects, exams, and how to describe academic life in Hindi.","culturalNote":"Education system in India: primary (praathamik — Classes 1-5), middle (madhyamik — 6-8), secondary (9-10 — SSC/SSLC board exams), higher secondary (11-12 — HSC/Intermediate). University (vishwavidyaalay): BA/BSc/BCom undergraduate; MA/MSc/MCom postgraduate; PhD (doctorate). Entrance exams are central: JEE (engineering — IITs), NEET (medicine), CAT (MBA — IIMs), CLAT (law), UPSC (civil services — the most prestigious and competitive). Coaching industry: Kota, Rajasthan is famous for JEE/NEET coaching — students leave home at 15 to study there. CBSE vs State Boards: CBSE (Central Board) is pan-India, each state also has its own board. Key subjects: Hindi, English, Maths (ganit), Science (vigyan), Social Studies (samajik vigyan), Sanskrit. Marks culture: parents ask ''kitne marks aaye?'' (how many marks did you get?) at every opportunity."},"examples":[{"sentence":"Main Delhi University mein Economics padhta hoon.","english":"I study Economics at Delhi University."},{"sentence":"Is saal main Board exam de raha hoon.","english":"This year I am giving the Board exam."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about school and university life in Hindi."}}',
'{"items":[{"word":"vishwavidyaalay","translation":"university","transliteration":"vishwavidyaalay","pronunciation":"vish-wa-vid-YAA-lay","example":"vishwavidyaalay mein padhna"},{"word":"pariksha","translation":"exam","transliteration":"pariksha","pronunciation":"pa-RICK-sha","example":"pariksha dena"},{"word":"vishay","translation":"subject","transliteration":"vishay","pronunciation":"vi-SHAY","example":"mera vishay"},{"word":"degree","translation":"degree","transliteration":"degree","pronunciation":"di-GREE","example":"degree lena"},{"word":"marks","translation":"marks/grades","transliteration":"marks","pronunciation":"marks","example":"acche marks"},{"word":"paas karna","translation":"to pass","transliteration":"paas karna","pronunciation":"paas KAR-na","example":"exam paas karna"}]}',
'{"title":"Main X mein Y padhta/padhti hoon — I study Y at X","pattern":"Main X mein Y padhta hoon (male) / padhti hoon (female) = I study Y at X. X mein = at X (location). Y = subject studied. padhna = to study/read. Agreement: padhta (male), padhti (female). Past: maine Y padha/padhi. Future: main Y padhunga/padhuungi.","explanation":"Studying at an institution: X mein padhna = to study at X. The institution takes mein (at/in). The subject is the direct object. Main college mein science padhta hoon = I study science at college. Variant: main X ka student hoon = I am a student of X. Exam phrases: pariksha dena (to give/sit an exam — Indian English: ''give exam'', not ''take exam''), pariksha paas karna (to pass an exam), fail hona (to fail). Result: pass ho gaya/gayi (passed), fail ho gaya/gayi (failed).","examples":[{"sentence":"Meri behen medical college mein padhti hai.","english":"My sister studies at medical college."},{"sentence":"Usne last year BA ki degree li.","english":"She took her BA degree last year."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"pariksha means?","options":["exam","subject","degree","class"],"correctAnswer":"exam"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I study Economics at Delhi University.","options":["Main Delhi University mein Economics padhta hoon.","Main Delhi University mein Science padhta hoon.","Main Mumbai University mein Economics padhta hoon.","Main Delhi University mein Economics padhti hoon."],"correctAnswer":"Main Delhi University mein Economics padhta hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Meri behen medical college mein ___ hai.","options":["padhti","padhta","padhte","padh rahi"],"correctAnswer":"padhti"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This year I am giving the Board exam.","wordBankItems":["Is","saal","main","Board","exam","de","raha","hoon","."],"correctAnswer":"Is saal main Board exam de raha hoon ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"paas karna means?","options":["to pass","to fail","to study","to prepare"],"correctAnswer":"to pass"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000056',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about work and office life in Hindi","Use naukri karna for having a job","Describe job roles and workplace"],"explanation":{"intro":"Work and office vocabulary covers job roles, workplace activities, and how to talk about your professional life in Hindi.","culturalNote":"Work culture in India: naukri (job — from Persian naukr = servant), kaam (work), daftar/office (office), boss (boss/sahib), colleague (saathi/colleague). Formal sector: IT (Bengaluru, Hyderabad, Pune), banking (Mumbai), government (Delhi). Government jobs (sarkari naukri) are highly prized for job security and benefits — competitive exams for IAS, IPS, IFS, SSC, banking (IBPS). Private sector: MNCs (multi-national companies), Indian conglomerates (Tata, Reliance, Mahindra, Birla). Working hours: 9-6 is common but IT companies often 9-9. Lunch: tiffin (tiffin = lunchbox — carried from home). Chai breaks (chai peena) are sacred. Workplace hierarchy: addressing seniors as ''sir'' or ''ma''am'' is universal. Holi, Diwali, company celebrations (kitty party). Appraisal cycle (performance appraisal — annual/semi-annual). Salary: maahvaari (monthly salary), hike (salary increment)."},"examples":[{"sentence":"Main ek IT company mein software engineer hoon.","english":"I am a software engineer at an IT company."},{"sentence":"Aaj office mein ek important meeting hai.","english":"Today there is an important meeting at the office."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about my work and office life in Hindi."}}',
'{"items":[{"word":"naukri","translation":"job/employment","transliteration":"naukri","pronunciation":"NAU-kri","example":"naukri karna"},{"word":"daftar","translation":"office","transliteration":"daftar","pronunciation":"DAF-tar","example":"daftar jaana"},{"word":"boss","translation":"boss/senior","transliteration":"boss","pronunciation":"boss","example":"mera boss"},{"word":"salary","translation":"salary","transliteration":"salary","pronunciation":"SA-la-ree","example":"salary milna"},{"word":"meeting","translation":"meeting","transliteration":"meeting","pronunciation":"MEE-ting","example":"meeting mein jaana"},{"word":"chhuti","translation":"leave/holiday off","transliteration":"chhuti","pronunciation":"CHHU-ti","example":"chhuti lena"}]}',
'{"title":"Main X mein Y hoon — I am Y at X (professional identity)","pattern":"Main X mein Y hoon = I am Y at X. X mein = at X (workplace). Y = job title. hoon = am (1st person singular of hona). Main TCS mein engineer hoon = I am an engineer at TCS. Past: main pehle X mein tha/thi = I was previously at X.","explanation":"Professional identity statement: main [company] mein [role] hoon. The role is a predicate noun — no agreement needed for nouns (only for adjectives). Main doctor hoon (I am a doctor), main teacher hoon (I am a teacher), main IT mein hoon (I am in IT). Ask: aap kya kaam karte hain? = What work do you do? / What is your job? (kya kaam = what work, karte hain = do — habitual). Answer: main [profession] hoon or main [place] mein [role] hoon.","examples":[{"sentence":"Wo ek bank mein manager hai.","english":"She/he is a manager at a bank."},{"sentence":"Mere pitaji government mein kaam karte hain.","english":"My father works in the government."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"naukri means?","options":["job/employment","work","office","salary"],"correctAnswer":"job/employment"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am a software engineer at an IT company.","options":["Main ek IT company mein software engineer hoon.","Main ek IT company mein manager hoon.","Main ek bank mein software engineer hoon.","Wo ek IT company mein software engineer hai."],"correctAnswer":"Main ek IT company mein software engineer hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mere pitaji government mein kaam ___ hain.","options":["karte","karta","karti","karte hue"],"correctAnswer":"karte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Today there is an important meeting at the office.","wordBankItems":["Aaj","office","mein","ek","important","meeting","hai","."],"correctAnswer":"Aaj office mein ek important meeting hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"chhuti means?","options":["leave/holiday off","salary","office","bonus"],"correctAnswer":"leave/holiday off"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000057',1,'APPROVED','PUBLISHED',
'{"objectives":["Plan a trip in Hindi","Use X jaane ka plan banana for making travel plans","Discuss transport and accommodation"],"explanation":{"intro":"Travel planning vocabulary covers booking tickets, choosing transport, discussing destinations, and planning an itinerary in Hindi.","culturalNote":"Travel in India: pilgrimage (tirth yatra = tirtha yatra) is one of the oldest and most common reasons for travel — Varanasi, Tirupati, Char Dham (four Hindu pilgrimage sites — Badrinath, Kedarnath, Gangotri, Yamunotri), Ajmer, Amritsar, Bodh Gaya. Family vacations: hill stations (pahadi ilaaka) — Shimla, Manali, Darjeeling, Ooty, Munnar. Beach: Goa (India''s most famous tourist destination — also very popular with domestic tourists), Andaman Islands, Kerala backwaters. Rail travel: Indian Railways is the world''s 4th largest railway network — 8,000+ stations, 13,000+ trains daily. IRCTC (Indian Railway Catering and Tourism Corporation) — online booking. Tatkal ticket (urgent ticket — premium price). Class: sleeper (3rd class berth), 3AC, 2AC, 1AC, general. AC bus: Volvo buses comfortable for medium distances. Flight: IndiGo, Air India, SpiceJet — domestic flights."},"examples":[{"sentence":"Hum agle mahine Goa jaane ka plan kar rahe hain.","english":"We are planning to go to Goa next month."},{"sentence":"Kya tumne train ticket book ki?","english":"Have you booked the train ticket?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can plan a trip and discuss transport and destinations in Hindi."}}',
'{"items":[{"word":"safar","translation":"journey/travel","transliteration":"safar","pronunciation":"SA-far","example":"safar karna"},{"word":"ticket","translation":"ticket","transliteration":"ticket","pronunciation":"TI-kat","example":"ticket book karna"},{"word":"destination","translation":"destination","transliteration":"destination","pronunciation":"des-ti-NAY-shun","example":"destination chunna"},{"word":"manzil","translation":"destination/goal","transliteration":"manzil","pronunciation":"MAN-zil","example":"manzil tak pahunchna"},{"word":"yatra","translation":"journey/pilgrimage","transliteration":"yatra","pronunciation":"YAT-ra","example":"tirth yatra"},{"word":"book karna","translation":"to book/reserve","transliteration":"book karna","pronunciation":"book KAR-na","example":"hotel book karna"}]}',
'{"title":"X jaane ka plan karna — to plan to go to X (infinitive + ka + plan)","pattern":"X jaane ka plan karna = to plan to go to X. Oblique infinitive: jaana → jaane. ka = possessive (plan of going). X = destination. Hum Goa jaane ka plan kar rahe hain = We are planning to go to Goa. Can also use: X jaane ki yojana banana (more formal) or X jaana chahte hain (want to go to X).","explanation":"Planning expression: [destination] jaane ka plan karna. Jaane = oblique infinitive of jaana (to go). Ka = possessive/genitive — plan of going. karna = to make/do. Present continuous: plan kar rahe hain (are planning). Alternative: jaana chahte hain (want to go — simpler). Also: [destination] jaane ki soch raha hoon = I am thinking of going to [destination]. Past: humne plan kiya tha (we had planned). Purpose: Goa jaane ke liye tickets book ki (booked tickets to go to Goa — ke liye = in order to).","examples":[{"sentence":"Maine agle hafte Jaipur jaane ka plan kiya hai.","english":"I have planned to go to Jaipur next week."},{"sentence":"Kya aap is baar kisi pahadi jagah jaane ka soch rahe hain?","english":"Are you thinking of going somewhere in the hills this time?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"safar means?","options":["journey/travel","destination","ticket","hotel"],"correctAnswer":"journey/travel"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We are planning to go to Goa next month.","options":["Hum agle mahine Goa jaane ka plan kar rahe hain.","Hum is mahine Goa jaane ka plan kar rahe hain.","Hum agle saal Goa jaane ka plan kar rahe hain.","Hum agle mahine Mumbai jaane ka plan kar rahe hain."],"correctAnswer":"Hum agle mahine Goa jaane ka plan kar rahe hain."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Maine agle hafte Jaipur jaane ka plan ___ hai.","options":["kiya","karna","kar raha","kiye"],"correctAnswer":"kiya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Have you booked the train ticket?","wordBankItems":["Kya","tumne","train","ticket","book","ki","?"],"correctAnswer":"Kya tumne train ticket book ki ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"manzil means?","options":["destination/goal","journey","ticket","route"],"correctAnswer":"destination/goal"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000058',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate a railway station in Hindi","Use X train kab hai for asking train times","Buy tickets and find platforms"],"explanation":{"intro":"At the railway station vocabulary covers buying tickets, asking about platforms and times, and navigating a busy Indian railway station in Hindi.","culturalNote":"Indian railways: Indian Railways is a national institution — 23 million passengers daily. Key vocabulary: platform (platform/plaatform), ticket counter (ticket khaana/counter), waiting room (pratiksha kaksha), reservation chart (reservation chart — pasted on train doors showing passenger names and seat numbers), TTE (Travelling Ticket Examiner — checks tickets on train), coolie/porter (coolie = luggage porter — distinctive red uniform). Announcements: ''kripaya platform number X par aayein'' = please come to platform X. Train types: Rajdhani (fastest — capital city connections), Shatabdi (fast daytime), Duronto (non-stop), Mail/Express, Passenger (slow local). Delays: Indian trains are notorious for delays — ''thodi der mein aayegi'' (it will come in a little while). IRCTC app for booking. Key: Indian station food — chai, vada pav, poori-sabzi — platform food culture is beloved."},"examples":[{"sentence":"Kripaya mujhe Delhi ki train ka platform bataaiye.","english":"Please tell me the platform for the Delhi train."},{"sentence":"Agla train kab hai?","english":"When is the next train?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate a railway station and ask about trains in Hindi."}}',
'{"items":[{"word":"platform","translation":"platform","transliteration":"platform","pronunciation":"PLAT-form","example":"platform number"},{"word":"ticket khaana","translation":"ticket office","transliteration":"ticket khaana","pronunciation":"TI-kat KHAA-na","example":"ticket khaana mein"},{"word":"coolie","translation":"porter/luggage carrier","transliteration":"coolie","pronunciation":"KOO-lee","example":"coolie bulaana"},{"word":"agla/agli","translation":"next (m/f)","transliteration":"agla/agli","pronunciation":"AG-la/AG-li","example":"agla station"},{"word":"reservation","translation":"reservation/booking","transliteration":"reservation","pronunciation":"re-zer-VAY-shun","example":"reservation karna"},{"word":"pahunchna","translation":"to arrive/reach","transliteration":"pahunchna","pronunciation":"pa-HUNCH-na","example":"station pahunchna"}]}',
'{"title":"X kab hai — When is X? (kab = when — question word)","pattern":"X kab hai? = When is X? Kab = when (question word for time). Agla train kab hai? = When is the next train? Bus kab aayegi? = When will the bus come? Answers: do baje (at 2 o''clock), ek ghante mein (in one hour), thodi der mein (in a little while).","explanation":"Kab (kab) = when. Question word for time. Used in direct questions: kab + aux verb. Also embedded: mujhe nahi pata kab aayegi (I don''t know when it will come). kab se = since when. kab tak = until when. Common railway: X kab tak aayegi? = When will X arrive by? The word ''kab'' can also express rhetorical meaning: kab aayega (when will he ever come? — implying frustration or doubt). Key time answers: abhi (right now), thodi der mein (in a little while), ek ghante mein (in an hour), shaam ko (in the evening).","examples":[{"sentence":"Rajdhani Express kab pahunchti hai?","english":"When does the Rajdhani Express arrive?"},{"sentence":"Platform number do par jaane ke liye seedhe jaiye.","english":"To go to platform number 2, go straight."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"platform means?","options":["platform","track","counter","waiting room"],"correctAnswer":"platform"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"When is the next train?","options":["Agla train kab hai?","Agli bus kab hai?","Agla train kab aayega?","Pichli train kab thi?"],"correctAnswer":"Agla train kab hai?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Rajdhani Express kab ___ hai?","options":["pahunchti","pahunchta","pahunchte","pahunche"],"correctAnswer":"pahunchti"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please tell me the platform for the Delhi train.","wordBankItems":["Kripaya","mujhe","Delhi","ki","train","ka","platform","bataaiye","."],"correctAnswer":"Kripaya mujhe Delhi ki train ka platform bataaiye ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"pahunchna means?","options":["to arrive/reach","to leave","to travel","to board"],"correctAnswer":"to arrive/reach"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000059',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a place in Hindi","Use yahan X hai aur Y bhi hai for listing features","Give a brief description of a city or landmark"],"explanation":{"intro":"Describing a place vocabulary covers how to describe cities, landmarks, and natural features in Hindi — useful for travel conversations and informal tour guides.","culturalNote":"India''s iconic places: Taj Mahal (Agra — UNESCO World Heritage — symbol of love — Shah Jahan built for Mumtaz Mahal — 17th century). Red Fort (Lal Qila — Delhi — Mughal fortress — Independence Day speech). Qutub Minar (Delhi — tallest brick minaret — 12th century). Golden Temple (Amritsar — Harmandir Sahib — holiest Sikh shrine — 24-hour langar). Varanasi ghats (ghats = stone steps to river — Hindu holiest city — Ganga Aarti). Kerala backwaters (houseboats — coconut groves). Hampi (Karnataka — Vijayanagara empire ruins — UNESCO). Khajuraho (MP — temple sculptures). Key: India has 42 UNESCO World Heritage Sites — 7th most in the world. Every state has iconic places — planning a trip means navigating an extraordinary diversity of landscapes and cultures."},"examples":[{"sentence":"Taj Mahal Agra mein hai, yah ek bahut sundar imarat hai.","english":"The Taj Mahal is in Agra, it is a very beautiful building."},{"sentence":"Yahan pahad, nadi aur ghane jangal hain.","english":"Here there are mountains, a river, and dense forests."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe a place in Hindi using key features and landmarks."}}',
'{"items":[{"word":"imarat","translation":"building/structure","transliteration":"imarat","pronunciation":"i-MAA-rat","example":"sundar imarat"},{"word":"ghat","translation":"river steps/landing","transliteration":"ghat","pronunciation":"ghaat","example":"Ganga ke ghaat"},{"word":"pahad","translation":"mountain/hill","transliteration":"pahad","pronunciation":"pa-HAAD","example":"oonche pahad"},{"word":"nadi","translation":"river","transliteration":"nadi","pronunciation":"NA-di","example":"saaf nadi"},{"word":"mashoor","translation":"famous","transliteration":"mashoor","pronunciation":"ma-SHOOR","example":"mashoor jagah"},{"word":"jagah","translation":"place/location","transliteration":"jagah","pronunciation":"JA-gah","example":"sundar jagah"}]}',
'{"title":"Yahan X, Y aur Z hain — Here there are X, Y and Z (listing features)","pattern":"Yahan X, Y aur Z hain = Here there are X, Y and Z. Yahan = here. hain = are (plural). Listing with aur (and). For a single item: yahan X hai. For multiple: yahan X, Y aur Z hain. Description chain: X mein Y hai, aur wahan Z bhi hai = In X there is Y, and there is also Z there.","explanation":"Place description template: start with location (Agra mein, yahan, wahan), then features (X hai/hain). Add details: bahut (very), ek famous (a famous), ka (of — possessive). Chain: Shimla mein bahut sundar pahad hain, yahan seb ke baag bhi hain aur mausam bhi accha rehta hai. = In Shimla there are very beautiful mountains, there are also apple orchards and the weather is also good. Key connecting words: aur (and), bhi (also/too), lekin (but), isliye (therefore).","examples":[{"sentence":"Jaipur mein bahut purane qile aur mahal hain.","english":"In Jaipur there are many old forts and palaces."},{"sentence":"Yeh jagah bahut mashoor hai kyunki yahaan ek prachin mandir hai.","english":"This place is very famous because there is an ancient temple here."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"mashoor means?","options":["famous","beautiful","ancient","popular"],"correctAnswer":"famous"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Taj Mahal is in Agra, it is a very beautiful building.","options":["Taj Mahal Agra mein hai, yah ek bahut sundar imarat hai.","Taj Mahal Delhi mein hai, yah ek bahut sundar imarat hai.","Taj Mahal Agra mein hai, yah ek purani imarat hai.","Taj Mahal Agra mein hai, yah ek bahut badi imarat hai."],"correctAnswer":"Taj Mahal Agra mein hai, yah ek bahut sundar imarat hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Jaipur mein bahut purane qile aur mahal ___ .","options":["hain","hai","tha","hote hain"],"correctAnswer":"hain"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Here there are mountains, a river, and dense forests.","wordBankItems":["Yahan","pahad",",","nadi","aur","ghane","jangal","hain","."],"correctAnswer":"Yahan pahad , nadi aur ghane jangal hain ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"jagah means?","options":["place/location","building","landmark","area"],"correctAnswer":"place/location"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000005a',1,'APPROVED','PUBLISHED',
'{"objectives":["Express cause and effect in Hindi","Use isliye for therefore and kyunki for because","Link reasons and results in sentences"],"explanation":{"intro":"Cause and effect vocabulary covers how to give reasons, explain outcomes, and use because and therefore in Hindi.","culturalNote":"Giving reasons in Hindi: kyunki (because — from kyun = why + ki = that), isliye (therefore — is = this + liye = for), kyunki...isliye (because...therefore — both in same sentence: kyunki baarish ho rahi thi, isliye hum ghar pe ruke = because it was raining, therefore we stayed home). Hindi discourse often starts with the result then gives the reason: main late aaya kyunki traffic tha = I came late because there was traffic. Reasons and excuses are very common in everyday Hindi — giving reasons for lateness (traffic, bijli gayi = electricity went, autorickshaw nahi mila = didn''t find an autorickshaw) is almost ritualistic. Cultural note: ''traffic'' is cited as a reason for everything in Indian cities — Delhi and Mumbai are among the world''s most congested cities."},"examples":[{"sentence":"Baarish ho rahi thi isliye hum nahi aaye.","english":"It was raining therefore we did not come."},{"sentence":"Main late aaya kyunki raaste mein traffic tha.","english":"I came late because there was traffic on the way."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express cause and effect using because and therefore in Hindi."}}',
'{"items":[{"word":"kyunki","translation":"because","transliteration":"kyunki","pronunciation":"KYUN-ki","example":"kyunki baarish hai"},{"word":"isliye","translation":"therefore/that''s why","transliteration":"isliye","pronunciation":"IS-li-ye","example":"isliye late hoon"},{"word":"wajah","translation":"reason/cause","transliteration":"wajah","pronunciation":"WA-jah","example":"kya wajah hai"},{"word":"nateeja","translation":"result/outcome","transliteration":"nateeja","pronunciation":"na-TEE-ja","example":"accha nateeja"},{"word":"traffic","translation":"traffic (congestion)","transliteration":"traffic","pronunciation":"TRA-fik","example":"traffic mein phansa"},{"word":"der","translation":"delay/lateness","transliteration":"der","pronunciation":"der","example":"der ho gayi"}]}',
'{"title":"Kyunki X, isliye Y — Because X, therefore Y (reason-result pair)","pattern":"Kyunki X, isliye Y = Because X, therefore Y. Kyunki (because) introduces the reason. Isliye (therefore) introduces the result. Both clauses are complete sentences. Order can be reversed: Y kyunki X = Y because X (no isliye needed when kyunki comes after the main clause). Most natural: main late aaya kyunki traffic tha (result first, then reason).","explanation":"Cause-effect connectors: kyunki (because) = subordinating conjunction introducing cause. Isliye (therefore/that''s why) = coordinating conjunction introducing result. Used together: kyunki X, isliye Y = because X, therefore Y (formal). More common in speech: result first + kyunki + cause. Examples: main thaka hoon kyunki kaam zyada tha (I am tired because there was a lot of work). Baarish ke wajah se nahi aaya (did not come because of rain — wajah se = because of, postpositional alternative to kyunki).","examples":[{"sentence":"Wo busy hai kyunki aaj uski meeting hai.","english":"She is busy because she has a meeting today."},{"sentence":"Bijli chali gayi isliye ghar andhera ho gaya.","english":"The electricity went so the house became dark."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"isliye means?","options":["therefore/that''s why","because","maybe","so that"],"correctAnswer":"therefore/that''s why"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"It was raining therefore we did not come.","options":["Baarish ho rahi thi isliye hum nahi aaye.","Baarish ho rahi thi kyunki hum nahi aaye.","Dhoop thi isliye hum nahi aaye.","Baarish ho rahi thi isliye wo nahi aaya."],"correctAnswer":"Baarish ho rahi thi isliye hum nahi aaye."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wo busy hai ___ aaj uski meeting hai.","options":["kyunki","isliye","lekin","aur"],"correctAnswer":"kyunki"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I came late because there was traffic on the way.","wordBankItems":["Main","late","aaya","kyunki","raaste","mein","traffic","tha","."],"correctAnswer":"Main late aaya kyunki raaste mein traffic tha ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"wajah means?","options":["reason/cause","result","problem","situation"],"correctAnswer":"reason/cause"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

